  }

  onPickerChange(event: MatDatepickerInputEvent<Date>): void {
    const value = event.value;
    if (value && value >= this.today) {
      this.selectDay(toIso(value));
    } else {
      (event.targetElement as HTMLInputElement).value = '';
    }
